with ranked as (select *, row_number() over (partition by location, dept_name order by budget desc nulls last, id) as row_num from departments qualify row_num = 1) select case when budget >= 4039000 then 'HIGH' else 'LOW' end as budget_tier, size(collect_set(location)) as num_locations, round(avg(budget), 2) as avg_budget from ranked group by case when budget >= 4039000 then 'HIGH' else 'LOW' end having size(collect_set(location)) < 1000 order by budget_tier;
